files.content:
// <file-card> — a single file card with an inline, type-aware preview.
//
// The files reinvention: a file is a content-addressed RECORD, so previewing it
// is a question of resolving its bytes and rendering them by `type` — image /
// audio / video play inline (video rides the wavelet path when the Host can
// transcode), text shows inline, anything else degrades to a typed icon +
// metadata. Content is resolved through the Host/Dock seam when docked (the
// nexus holds the content-addressed blob); standalone it falls back to a `src`
// URL or `text`, otherwise a typed placeholder. No bytes are ever required for
// the card to render — metadata alone is enough.
//
// Source resolution, in order:
//   • `src`  — a directly fetchable URL (image/audio/video/text by URL)
//   • `text` — inline text content (a code/markdown/csv snippet)
//   • `path` + a docked Host — content fetched via this.host (`/files/get`)
//   • otherwise — a typed placeholder + metadata (degraded but complete)
//
// Usage:
//   <file-card name="logo.svg" type="image/svg+xml" src="./logo.svg"></file-card>
//   <file-card name="readme.md" type="text/markdown" text="# Hello"></file-card>
//   <file-card name="clip.mp4" type="video/mp4" path="blobs/abc" size="91234"></file-card>
//
// Attributes:
//   name      file name (shown as the title)
//   type      mime/type or extension (drives the preview)
//   src       a fetchable URL for the content (image/audio/video/text)
//   text      inline text content
//   path      content key/path (resolved via the Host when docked)
//   hash      content-hash (shown in metadata)
//   size      byte size (shown in metadata)
//   modified  modified timestamp (shown in metadata)
//   variant   card | bare      (visual shell)
//   density   sm | md | lg      (preview height)
//
// Events:
//   work-file-open  { detail: { file } }   fired when the preview/title is opened
import { WbElement, html, css, define } from "../../core/element.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";
import { fileKind, kindGlyph, fmtBytes, fmtWhen, shortHash, extOf } from "./file-types.js";

const VARIANTS = defineVariants({
  variant: { options: ["card", "bare"], default: "card" },
  density: { options: ["sm", "md", "lg"], default: "md" },
});

export class WbFile extends WbElement {
  static variants = VARIANTS;
  static props = [
    ...variantAttrs(VARIANTS),
    "name", "type", "src", "text", "path", "hash", "size", "modified",
  ];

  // The element reads its state via this.attr() in render() and drives its own
  // repaints (requestUpdate / _resolveContent) from attributeChangedCallback —
  // so it must observe every prop attribute itself.
  static get observedAttributes() { return this.props; }

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .card { border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); overflow: hidden; box-shadow: var(--work-shadow-sm);
      display: flex; flex-direction: column; }
    :host([variant="bare"]) .card { border: none; box-shadow: none; background: transparent; }

    .head { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3); border-bottom: 1px solid var(--work-border);
      background: var(--work-surface-soft); }
    .badge { width: 26px; height: 26px; flex: none; display: grid; place-items: center;
      border-radius: var(--work-radius-sm); font-size: var(--work-text); background: var(--work-surface); color: var(--work-fg-muted); }
    .badge[data-kind="image"] { background: var(--work-chip-lavender); color: var(--work-brand-ink); }
    .badge[data-kind="video"] { background: var(--work-chip-peach);    color: var(--work-brand-ink); }
    .badge[data-kind="audio"] { background: var(--work-chip-green);    color: var(--work-brand-ink); }
    .badge[data-kind="text"]  { background: var(--work-chip-blue);     color: var(--work-brand-ink); }
    .title { font-weight: 600; font-size: var(--work-text); letter-spacing: -.005em;
      overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }
    .title:hover { color: var(--work-brand); }
    .grow { flex: 1; }
    .typetag { font-family: var(--work-font-mono); font-size: var(--work-text-2xs); text-transform: uppercase;
      letter-spacing: .04em; color: var(--work-fg-subtle); }

    /* preview stage */
    .stage { position: relative; display: flex; align-items: center; justify-content: center;
      background:
        repeating-conic-gradient(color-mix(in srgb, var(--work-fg) 4%, transparent) 0% 25%, transparent 0% 50%) 50% / 20px 20px,
        var(--work-bg);
      min-height: var(--_h, 220px); max-height: var(--_h, 220px); overflow: hidden; }
    :host([density="sm"]) .stage { --_h: 140px; }
    :host([density="lg"]) .stage { --_h: 340px; }

    .stage img { max-width: 100%; max-height: var(--_h, 220px); object-fit: contain; display: block; }
    .stage video { max-width: 100%; max-height: var(--_h, 220px); background: var(--work-scrim); }
    .stage audio { width: 90%; }
    .audio-wrap { display: flex; flex-direction: column; align-items: center; gap: var(--work-space-3); width: 100%; padding: var(--work-space-4); }
    .audio-glyph { font-size: var(--work-glyph-lg); color: var(--work-brand); }

    .textview { width: 100%; height: var(--_h, 220px); margin: 0; overflow: auto;
      padding: var(--work-space-3); box-sizing: border-box;
      font-family: var(--work-font-mono); font-size: var(--work-text-sm); line-height: 1.5;
      color: var(--work-fg); background: var(--work-surface); white-space: pre-wrap; word-break: break-word; text-align: left; }

    .placeholder { display: flex; flex-direction: column; align-items: center; gap: var(--work-space-2);
      color: var(--work-fg-muted); padding: var(--work-space-5); text-align: center; }
    .ph-glyph { width: 64px; height: 64px; display: grid; place-items: center; font-size: var(--work-text-metric);
      border-radius: var(--work-radius); background: var(--work-surface); color: var(--work-fg-muted);
      border: 1px solid var(--work-border); }
    .ph-glyph[data-kind="image"] { background: var(--work-chip-lavender); color: var(--work-brand-ink); }
    .ph-glyph[data-kind="video"] { background: var(--work-chip-peach);    color: var(--work-brand-ink); }
    .ph-glyph[data-kind="audio"] { background: var(--work-chip-green);    color: var(--work-brand-ink); }
    .ph-glyph[data-kind="text"]  { background: var(--work-chip-blue);     color: var(--work-brand-ink); }
    .ph-ext { font-family: var(--work-font-mono); font-size: var(--work-text-xs); }
    .ph-note { font-size: var(--work-text-sm); }
    .status { color: var(--work-fg-muted); font-family: var(--work-font-mono); font-size: var(--work-text-sm); padding: var(--work-space-4); }
    .status.err { color: var(--work-err); white-space: pre-wrap; }

    /* metadata footer */
    .meta { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
      gap: var(--work-space-1) var(--work-space-4); padding: var(--work-space-2) var(--work-space-3);
      border-top: 1px solid var(--work-border); }
    .m { display: flex; flex-direction: column; gap: var(--work-space-px); min-width: 0; }
    .m .k { font-family: var(--work-font-mono); font-size: var(--work-text-3xs); text-transform: uppercase;
      letter-spacing: .05em; color: var(--work-fg-subtle); }
    .m .v { font-size: var(--work-text-sm); color: var(--work-fg); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    .m .v.mono { font-family: var(--work-font-mono); font-size: var(--work-text-xs); color: var(--work-fg-muted); }
    .docked { font-family: var(--work-font-mono); font-size: var(--work-text-3xs); }
  `;

  connectedCallback() {
    if (this._init == null) {
      this._init = true;
      this._objUrl = null;   // a blob URL we created (revoked on change/disconnect)
      this._resolved = null; // {url} | {text} from the Host
      this._error = null;
      this._busy = false;
    }
    super.connectedCallback();
    this._resolveContent();
    this._connected = true;
  }

  disconnectedCallback() { super.disconnectedCallback(); this._revoke(); }

  attributeChangedCallback(name, old, val) {
    // NB: this element reads state via this.attr() in render() and drives its own
    // repaints, so it does NOT delegate to Lit's attributeChangedCallback (whose
    // property machinery is unused here) — that path would throw.
    if (!this._connected) return;
    if (["src", "text", "path", "type"].includes(name)) this._resolveContent();
    else this.requestUpdate(); // name/hash/size/modified change the card copy → repaint
  }

  _revoke() { if (this._objUrl) { try { URL.revokeObjectURL(this._objUrl); } catch {} this._objUrl = null; } }

  get _kind() { return fileKind(this.attr("type"), this.attr("name")); }

  /** Resolve previewable content. Direct src/text need nothing; a `path` is
   *  fetched via the Host when a runtime is docked. Never blocks the card. */
  async _resolveContent() {
    this._revoke();
    this._resolved = null;
    this._error = null;
    // Direct URL / inline text — no resolution needed.
    if (this.attr("src") || this.attr("text") != null) { this.requestUpdate(); return; }
    const path = this.attr("path");
    if (!path) { this.requestUpdate(); return; }       // metadata-only → typed placeholder
    if (!this.host.available("files")) { this.requestUpdate(); return; } // standalone, no Host
    // Docked: ask the Host for the content-addressed blob.
    this._busy = true; this.requestUpdate();
    try {
      const out = await this.host.request("/files/get", { body: { path, hash: this.attr("hash") } });
      if (out && out.url) this._resolved = { url: out.url };
      else if (out && out.text != null) this._resolved = { text: out.text };
      else if (out && out.dataUrl) this._resolved = { url: out.dataUrl };
    } catch (e) {
      this._error = String((e && e.message) || e);
    }
    this._busy = false;
    this.requestUpdate();
  }

  /** The URL to render media from (direct src or a Host-resolved blob). */
  _mediaUrl() { return this.attr("src") || (this._resolved && this._resolved.url) || null; }
  /** The text to render (inline attr or Host-resolved). */
  _textContent() {
    const t = this.attr("text");
    if (t != null) return t;
    return this._resolved && this._resolved.text != null ? this._resolved.text : null;
  }

  render() {
    const name = this.attr("name") || "Untitled";
    const type = this.attr("type") || "";
    const kind = this._kind;
    const ext = extOf(name) || extOf(type);
    return html`<div class="card">
      <div class="head">
        <span class="badge" data-kind=${kind}>${kindGlyph(kind)}</span>
        <span class="title" title=${name} @click=${this._open}>${name}</span>
        <span class="grow"></span>
        <span class="typetag">${type || ext || kind}</span>
      </div>
      <div class="stage">${this._renderPreview(kind)}</div>
      ${this._renderMeta()}
    </div>`;
  }

  _renderPreview(kind) {
    if (this._busy) return html`<div class="status">Resolving content…</div>`;
    if (this._error) return html`<div class="status err">Could not load — ${this._error}</div>`;
    const url = this._mediaUrl();
    const text = this._textContent();

    if (kind === "image" && url) return html`<img src=${url} alt=${this.attr("name") || ""} @click=${this._open} />`;
    if (kind === "video" && url) return html`<video src=${url} controls preload="metadata"></video>`;
    if (kind === "audio" && url) {
      return html`<div class="audio-wrap"><span class="audio-glyph">${kindGlyph("audio")}</span>
        <audio src=${url} controls></audio></div>`;
    }
    if ((kind === "text" || kind === "code") && text != null) {
      const clipped = text.length > 8000 ? text.slice(0, 8000) + "\n…" : text;
      return html`<pre class="textview">${clipped}</pre>`;
    }
    // text/code with a URL but no inline content, and no Host text → placeholder
    return this._renderPlaceholder(kind);
  }

  _renderPlaceholder(kind) {
    const ext = extOf(this.attr("name")) || extOf(this.attr("type"));
    const path = this.attr("path");
    const note = path && !this.host.available("files")
      ? "Content lives in the nexus — dock a runtime to preview."
      : (kind === "video"
          ? "Preview / transcode via the wavelet path when docked."
          : "No preview — metadata only.");
    return html`<div class="placeholder">
      <span class="ph-glyph" data-kind=${kind}>${kindGlyph(kind)}</span>
      ${ext ? html`<span class="ph-ext">.${ext}</span>` : null}
      <span class="ph-note">${note}</span>
    </div>`;
  }

  _renderMeta() {
    const items = [];
    const type = this.attr("type");
    const size = this.attr("size");
    const modified = this.attr("modified");
    const hash = this.attr("hash");
    const path = this.attr("path");
    if (type) items.push(["Type", type, false]);
    if (size != null && size !== "") items.push(["Size", fmtBytes(size), true]);
    if (modified) items.push(["Modified", fmtWhen(modified), false]);
    if (hash) items.push(["Content hash", shortHash(hash), true]);
    if (path) items.push(["Path", path, true]);
    if (!items.length) return null;
    const docked = path
      ? html`<span class="m"><span class="k">Source</span><span class="v">
          <span class="docked" style=${`color:var(${this.host.available("files") ? "--work-ok" : "--work-fg-subtle"})`}>${this.host.available("files") ? "● docked" : "○ standalone"}</span>
        </span></span>`
      : null;
    return html`<div class="meta">${items.map(([k, v, mono]) =>
      html`<span class="m"><span class="k">${k}</span><span class="v ${mono ? "mono" : ""}" title=${v}>${v}</span></span>`)}
      ${docked}
    </div>`;
  }

  _open = () => this.dispatchEvent(new CustomEvent("work-file-open", {
    detail: { file: this._file() }, bubbles: true, composed: true }));

  _file() {
    const o = {};
    for (const a of ["name", "type", "src", "path", "hash", "size", "modified"]) {
      const v = this.attr(a); if (v != null) o[a] = v;
    }
    return o;
  }
}

define("file-card", WbFile);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// files · shared type helpers — pure, zero-dep, DOM-free. Both <wb-drive> and
// <wb-file> classify a file by its mime/type or extension into a small kind set
// (image | video | audio | text | pdf | archive | code | font | file), pick a
// typed glyph, and format size/timestamps. One home, no copy-paste.

const EXT_KIND = {
  // images
  png: "image", jpg: "image", jpeg: "image", gif: "image", webp: "image",
  svg: "image", avif: "image", bmp: "image", ico: "image", heic: "image",
  // video
  mp4: "video", webm: "video", mov: "video", mkv: "video", avi: "video", m4v: "video",
  // audio
  mp3: "audio", wav: "audio", ogg: "audio", flac: "audio", m4a: "audio", aac: "audio",
  // text / docs
  txt: "text", md: "text", org: "text", rst: "text", log: "text", csv: "text",
  // pdf
  pdf: "pdf",
  // code
  js: "code", mjs: "code", ts: "code", jsx: "code", tsx: "code", json: "code",
  html: "code", css: "code", py: "code", rs: "code", go: "code", c: "code",
  cpp: "code", h: "code", ex: "code", exs: "code", sh: "code", sql: "code",
  yaml: "code", yml: "code", toml: "code", xml: "code",
  // archives
  zip: "archive", tar: "archive", gz: "archive", tgz: "archive", rar: "archive",
  "7z": "archive", bz2: "archive",
  // fonts
  woff: "font", woff2: "font", ttf: "font", otf: "font",
};

const GLYPH = {
  image: "🖼", video: "🎞", audio: "♪", text: "📄", pdf: "📕",
  code: "{ }", archive: "🗜", font: "Aa", file: "📦",
};

/** Lowercase extension (no dot) from a name or "image/png" → "png". */
export function extOf(s) {
  if (!s) return "";
  s = String(s);
  if (s.includes("/")) return s.split("/").pop().split("+")[0].toLowerCase(); // a mime subtype
  const dot = s.lastIndexOf(".");
  return dot >= 0 ? s.slice(dot + 1).toLowerCase() : "";
}

/** Classify into a kind from a mime/type string and/or a filename. */
export function fileKind(type, name) {
  const t = String(type || "").toLowerCase();
  if (t.startsWith("image/")) return "image";
  if (t.startsWith("video/")) return "video";
  if (t.startsWith("audio/")) return "audio";
  if (t === "application/pdf") return "pdf";
  if (t.startsWith("text/")) return "text";
  if (/(zip|x-tar|gzip|x-7z|x-rar)/.test(t)) return "archive";
  if (t.startsWith("font/")) return "font";
  if (/(javascript|json|html|xml|x-sh|x-python)/.test(t)) return "code";
  // fall back to the extension of name (or a bare ext in `type`)
  const ext = extOf(name) || (t && !t.includes("/") ? t : "");
  return EXT_KIND[ext] || "file";
}

/** A typed glyph for a kind (text-only; renders in any theme). */
export function kindGlyph(kind) { return GLYPH[kind] || GLYPH.file; }

/** Human byte size: 1536 → "1.5 KB". Accepts number or numeric string. */
export function fmtBytes(n) {
  n = Number(n);
  if (!isFinite(n) || n < 0) return "—";
  if (n < 1024) return `${n} B`;
  const u = ["KB", "MB", "GB", "TB"];
  let i = -1;
  do { n /= 1024; i++; } while (n >= 1024 && i < u.length - 1);
  return `${n < 10 ? n.toFixed(1) : Math.round(n)} ${u[i]}`;
}

/** Friendly timestamp: ISO/epoch → "Nov 3, 2024". Best-effort, never throws. */
export function fmtWhen(v) {
  if (v == null || v === "") return "—";
  let d;
  if (typeof v === "number") d = new Date(v < 1e12 ? v * 1000 : v); // s vs ms epoch
  else d = new Date(v);
  if (isNaN(d.getTime())) return String(v);
  return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

/** Short content-hash for display: "sha256:abcd…1234" → "abcd…1234". */
export function shortHash(h) {
  if (!h) return "";
  h = String(h).replace(/^[a-z0-9]+:/i, "");
  return h.length > 14 ? `${h.slice(0, 8)}…${h.slice(-4)}` : h;
}
